<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>二次函数的 a、b、c 与抛物线</title>
<style>
  :root{
    --bg:#0f1720;
    --fg:#e8eef4;
    --accent:#b48ead;
    --panel:#17222e;
    --muted:#9fb0c0;
    --grid:#26364a;
    --axis:#55708a;
    --curve:#b48ead;
    --vertex:#4cc9f0;
    --root:#7ee787;
    --yint:#f7b955;
  }
  *{box-sizing:border-box;}
  body{
    margin:0;padding:16px;
    background:var(--bg);color:var(--fg);
    font-family:system-ui,-apple-system,"Segoe UI",Roboto,"Helvetica Neue",Arial,"PingFang SC","Microsoft YaHei",sans-serif;
    line-height:1.5;
  }
  .wrap{max-width:920px;margin:0 auto;}
  h1{font-size:1.15rem;margin:0 0 4px;font-weight:650;}
  .sub{color:var(--muted);font-size:.85rem;margin:0 0 14px;}
  .eq{
    background:var(--panel);border:1px solid var(--grid);border-radius:10px;
    padding:10px 14px;margin-bottom:12px;font-size:1rem;
    font-variant-numeric:tabular-nums;overflow-x:auto;white-space:nowrap;
  }
  .eq b{color:var(--accent);}
  .controls{
    display:grid;grid-template-columns:repeat(3,1fr);gap:12px;
    background:var(--panel);border:1px solid var(--grid);
    border-radius:10px;padding:12px 14px;margin-bottom:12px;
  }
  @media (max-width:640px){ .controls{grid-template-columns:1fr;} }
  .ctrl{display:flex;flex-direction:column;gap:6px;}
  .ctrl label{font-size:.9rem;display:flex;justify-content:space-between;align-items:baseline;gap:8px;}
  .ctrl label b{color:var(--accent);font-variant-numeric:tabular-nums;}
  input[type=range]{width:100%;accent-color:var(--accent);cursor:pointer;height:22px;}
  input[type=range]:focus-visible{outline:2px solid var(--accent);outline-offset:3px;border-radius:4px;}
  .canvas-box{
    background:var(--panel);border:1px solid var(--grid);
    border-radius:10px;padding:8px;
  }
  canvas{display:block;width:100%;height:auto;border-radius:6px;}
  .legend{display:flex;flex-wrap:wrap;gap:14px;font-size:.78rem;color:var(--muted);margin-top:10px;}
  .legend span{display:flex;align-items:center;gap:6px;}
  .dot{width:11px;height:11px;border-radius:50%;display:inline-block;}
  .readout{
    display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));
    gap:8px;margin-top:12px;
  }
  .stat{background:var(--panel);border:1px solid var(--grid);border-radius:8px;padding:8px 10px;}
  .stat .k{color:var(--muted);font-size:.75rem;}
  .stat .v{font-size:1rem;font-weight:600;font-variant-numeric:tabular-nums;}
  .stat .v.accent{color:var(--accent);}
  .stat .v.vertex{color:var(--vertex);}
  .stat .v.root{color:var(--root);}
  .note{color:var(--muted);font-size:.78rem;margin-top:10px;}
</style>
</head>
<body>
<div class="wrap">
  <h1>二次函数的 a、b、c 与抛物线</h1>
  <p class="sub">y = a·x² + b·x + c，纵轴 [−10,10]，横轴 [−10,10]；a ≠ 0</p>

  <div class="eq" id="eq"></div>

  <div class="controls">
    <div class="ctrl">
      <label for="a">a（开口方向/宽窄） <b><output id="aOut">1.0</output></b></label>
      <input id="a" type="range" min="-3" max="3" step="0.1" value="1"
             aria-label="系数 a，范围负 3 到 3，步长 0.1，不为 0">
    </div>
    <div class="ctrl">
      <label for="b">b（对称轴） <b><output id="bOut">0.0</output></b></label>
      <input id="b" type="range" min="-8" max="8" step="0.2" value="0"
             aria-label="系数 b，范围负 8 到 8，步长 0.2">
    </div>
    <div class="ctrl">
      <label for="c">c（y 轴截距） <b><output id="cOut">0.0</output></b></label>
      <input id="c" type="range" min="-8" max="8" step="0.2" value="0"
             aria-label="系数 c，范围负 8 到 8，步长 0.2">
    </div>
  </div>

  <div class="canvas-box">
    <canvas id="cv" width="900" height="480" role="img"
            aria-label="抛物线图像，标出顶点、y 轴截距与实根"></canvas>
  </div>

  <div class="legend" aria-hidden="true">
    <span><i class="dot" style="background:#b48ead"></i>抛物线</span>
    <span><i class="dot" style="background:#4cc9f0"></i>顶点</span>
    <span><i class="dot" style="background:#f7b955"></i>y 轴截距 (0,c)</span>
    <span><i class="dot" style="background:#7ee787"></i>实根（与 x 轴交点）</span>
  </div>

  <div class="readout">
    <div class="stat"><div class="k">对称轴 x = −b/(2a)</div><div class="v vertex" id="axisOut">0.00</div></div>
    <div class="stat"><div class="k">顶点</div><div class="v vertex" id="vertexOut">(0.00, 0.00)</div></div>
    <div class="stat"><div class="k">最值（顶点 y）</div><div class="v vertex" id="extremumOut">0.00</div></div>
    <div class="stat"><div class="k">判别式 Δ = b²−4ac</div><div class="v accent" id="discOut">0.00</div></div>
    <div class="stat"><div class="k">与 x 轴交点</div><div class="v root" id="rootsOut">x = 0</div></div>
    <div class="stat"><div class="k">开口</div><div class="v" id="dirOut">向上</div></div>
  </div>

  <p class="note">曲线与标注均由公式计算；超出窗口的图线被裁切。a 滑块不会取 0，保证始终是二次函数。</p>
</div>

<script>
(function(){
  "use strict";

  var cv = document.getElementById("cv");
  var ctx = cv.getContext("2d");
  var aEl = document.getElementById("a");
  var bEl = document.getElementById("b");
  var cEl = document.getElementById("c");
  var aOut = document.getElementById("aOut");
  var bOut = document.getElementById("bOut");
  var cOut = document.getElementById("cOut");
  var eqEl = document.getElementById("eq");
  var axisOut = document.getElementById("axisOut");
  var vertexOut = document.getElementById("vertexOut");
  var extremumOut = document.getElementById("extremumOut");
  var discOut = document.getElementById("discOut");
  var rootsOut = document.getElementById("rootsOut");
  var dirOut = document.getElementById("dirOut");

  var X_MIN = -10, X_MAX = 10, Y_MIN = -10, Y_MAX = 10;

  function clamp(v, lo, hi){ return Math.min(hi, Math.max(lo, v)); }
  function num(v, d){ return (typeof v === "number" && isFinite(v)) ? v : d; }
  function fmt(v, d){
    var s = v.toFixed(d === undefined ? 2 : d);
    if (s === "-0.00") s = "0.00";
    return s;
  }

  var state = genui.getState() || {};
  var a = clamp(num(state.a, 1), -3, 3);
  var b = clamp(num(state.b, 0), -8, 8);
  var c = clamp(num(state.c, 0), -8, 8);
  if (a === 0) a = 1;

  aEl.value = String(a);
  bEl.value = String(b);
  cEl.value = String(c);

  function saveState(){
    genui.setState({ a: a, b: b, c: c });
  }

  function solveRoots(a, b, c){
    var disc = b*b - 4*a*c;
    if (disc > 1e-12){
      var sq = Math.sqrt(disc);
      var r1 = (-b - sq) / (2*a);
      var r2 = (-b + sq) / (2*a);
      return { disc: disc, kind: 2, roots: [Math.min(r1, r2), Math.max(r1, r2)] };
    } else if (disc >= -1e-12){
      return { disc: 0, kind: 1, roots: [-b / (2*a)] };
    }
    return { disc: disc, kind: 0, roots: [] };
  }

  function fmtPoly(){
    function term(coef, varPart){
      if (coef === 0) return "";
      var sign = coef < 0 ? " − " : " + ";
      var abs = Math.abs(coef);
      var coefStr = (abs === 1 && varPart) ? "" : (Number.isInteger(abs) ? String(abs) : abs.toFixed(1));
      return sign + coefStr + varPart;
    }
    var s = "y = ";
    var aAbs = Math.abs(a);
    s += (a < 0 ? "−" : "") + ((aAbs === 1) ? "" : (Number.isInteger(aAbs) ? String(aAbs) : aAbs.toFixed(1))) + "x²";
    var bt = term(b, "x");
    s += bt === "" ? "" : bt;
    var ct = term(c, "");
    s += ct === "" ? "" : ct;
    return s;
  }

  function updateTexts(){
    aOut.textContent = a.toFixed(1);
    bOut.textContent = b.toFixed(1);
    cOut.textContent = c.toFixed(1);
    eqEl.innerHTML = fmtPoly().replace(/x²/g, "x<sup>2</sup>").replace(/</g, "&lt;").replace(/&lt;sup&gt;/g, "<sup>").replace(/&lt;\/sup&gt;/g, "</sup>");

    var axis = -b / (2*a);
    var vy = a*axis*axis + b*axis + c;
    axisOut.textContent = fmt(axis);
    vertexOut.textContent = "(" + fmt(axis) + ", " + fmt(vy) + ")";
    extremumOut.textContent = fmt(vy);
    var sol = solveRoots(a, b, c);
    discOut.textContent = fmt(sol.disc);
    if (sol.kind === 2) rootsOut.textContent = "x₁=" + fmt(sol.roots[0]) + "，x₂=" + fmt(sol.roots[1]);
    else if (sol.kind === 1) rootsOut.textContent = "x = " + fmt(sol.roots[0]) + "（重根）";
    else rootsOut.textContent = "无实根";
    dirOut.textContent = (a > 0 ? "向上" : "向下") + "（|a|=" + Math.abs(a).toFixed(1) + "）";
  }

  function draw(){
    var W = cv.width, H = cv.height;
    var pad = 34;
    var plotW = W - pad*2, plotH = H - pad*2;

    function xOf(x){ return pad + (x - X_MIN) / (X_MAX - X_MIN) * plotW; }
    function yOf(y){ return pad + (Y_MAX - y) / (Y_MAX - Y_MIN) * plotH; }

    ctx.clearRect(0, 0, W, H);
    ctx.fillStyle = "#101a24";
    ctx.fillRect(pad, pad, plotW, plotH);

    // 网格
    ctx.strokeStyle = "#26364a";
    ctx.lineWidth = 1;
    ctx.fillStyle = "#9fb0c0";
    ctx.font = "11px system-ui, sans-serif";
    ctx.textAlign = "center";
    ctx.textBaseline = "top";
    for (var gx = X_MIN; gx <= X_MAX; gx += 2){
      var px = xOf(gx);
      ctx.beginPath(); ctx.moveTo(px, pad); ctx.lineTo(px, pad + plotH); ctx.stroke();
      ctx.fillText(String(gx), px, pad + plotH + 6);
    }
    ctx.textAlign = "right";
    ctx.textBaseline = "middle";
    for (var gy = Y_MIN; gy <= Y_MAX; gy += 2){
      var py = yOf(gy);
      ctx.beginPath(); ctx.moveTo(pad, py); ctx.lineTo(pad + plotW, py); ctx.stroke();
      ctx.fillText(String(gy), pad - 6, py);
    }

    // 坐标轴
    ctx.strokeStyle = "#55708a";
    ctx.lineWidth = 1.6;
    var x0 = xOf(0), y0 = yOf(0);
    ctx.beginPath(); ctx.moveTo(pad, y0); ctx.lineTo(pad + plotW, y0); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(x0, pad); ctx.lineTo(x0, pad + plotH); ctx.stroke();

    // 轴标签
    ctx.fillStyle = "#9fb0c0";
    ctx.font = "12px system-ui, sans-serif";
    ctx.textAlign = "right"; ctx.textBaseline = "bottom";
    ctx.fillText("x", pad + plotW, y0 - 4);
    ctx.textAlign = "left"; ctx.textBaseline = "top";
    ctx.fillText("y", x0 + 6, pad - 2);

    // 抛物线
    var steps = 900;
    ctx.beginPath();
    var started = false;
    for (var i = 0; i <= steps; i++){
      var xx = X_MIN + (i / steps) * (X_MAX - X_MIN);
      var yy = a*xx*xx + b*xx + c;
      if (yy < Y_MIN - 1 || yy > Y_MAX + 1){
        started = false;
        continue;
      }
      var qx = xOf(xx), qy = yOf(clamp(yy, Y_MIN - 1, Y_MAX + 1));
      if (!started){ ctx.moveTo(qx, qy); started = true; }
      else ctx.lineTo(qx, qy);
    }
    ctx.strokeStyle = "#b48ead";
    ctx.lineWidth = 2.6;
    ctx.lineJoin = "round";
    ctx.lineCap = "round";
    ctx.stroke();

    // 对称轴虚线
    var axisX = -b / (2*a);
    if (axisX >= X_MIN && axisX <= X_MAX){
      ctx.save();
      ctx.setLineDash([6, 6]);
      ctx.strokeStyle = "rgba(76,201,240,0.45)";
      ctx.lineWidth = 1.4;
      ctx.beginPath(); ctx.moveTo(xOf(axisX), pad); ctx.lineTo(xOf(axisX), pad + plotH); ctx.stroke();
      ctx.restore();
    }

    // y 轴截距
    if (c >= Y_MIN && c <= Y_MAX){
      ctx.fillStyle = "#f7b955";
      ctx.beginPath(); ctx.arc(xOf(0), yOf(c), 5, 0, Math.PI*2); ctx.fill();
      ctx.fillStyle = "#f7b955";
      ctx.font = "11px system-ui, sans-serif";
      ctx.textAlign = "left"; ctx.textBaseline = "bottom";
      ctx.fillText("(0," + fmt(c,1) + ")", xOf(0) + 8, yOf(c) - 4);
    }

    // 实根
    var sol = solveRoots(a, b, c);
    for (var r = 0; r < sol.roots.length; r++){
      var rx = sol.roots[r];
      if (rx >= X_MIN && rx <= X_MAX){
        ctx.fillStyle = "#7ee787";
        ctx.beginPath(); ctx.arc(xOf(rx), yOf(0), 5, 0, Math.PI*2); ctx.fill();
        ctx.fillStyle = "#7ee787";
        ctx.font = "11px system-ui, sans-serif";
        ctx.textAlign = "center"; ctx.textBaseline = "top";
        ctx.fillText("x=" + fmt(rx,1), xOf(rx), yOf(0) + 6);
      }
    }

    // 顶点
    var vy = a*axisX*axisX + b*axisX + c;
    if (axisX >= X_MIN && axisX <= X_MAX && vy >= Y_MIN && vy <= Y_MAX){
      ctx.fillStyle = "#4cc9f0";
      ctx.beginPath(); ctx.arc(xOf(axisX), yOf(vy), 6, 0, Math.PI*2); ctx.fill();
      ctx.strokeStyle = "#0f1720"; ctx.lineWidth = 2; ctx.stroke();
      ctx.fillStyle = "#4cc9f0";
      ctx.font = "bold 11px system-ui, sans-serif";
      ctx.textAlign = "left"; ctx.textBaseline = "top";
      ctx.fillText("顶点 (" + fmt(axisX,1) + "," + fmt(vy,1) + ")", xOf(axisX) + 9, yOf(vy) + 6);
    }
  }

  function refresh(){
    updateTexts();
    draw();
  }

  function onA(){
    var v = clamp(parseFloat(aEl.value) || 0, -3, 3);
    if (v === 0) v = (a >= 0 ? 0.1 : -0.1);
    a = v;
    aEl.value = String(a);
    saveState(); refresh();
  }
  function onB(){
    b = clamp(parseFloat(bEl.value) || 0, -8, 8);
    saveState(); refresh();
  }
  function onC(){
    c = clamp(parseFloat(cEl.value) || 0, -8, 8);
    saveState(); refresh();
  }

  aEl.addEventListener("input", onA);
  bEl.addEventListener("input", onB);
  cEl.addEventListener("input", onC);

  saveState();
  refresh();
})();
</script>
</body>
</html>
